import{_ as o,o as a,c as t,a0 as s}from"./chunks/framework.BSa2j5Vp.js";const m=JSON.parse('{"title":"Models and effort","description":"","frontmatter":{},"headers":[],"relativePath":"guide/models.md","filePath":"guide/models.md"}'),r={name:"guide/models.md"};function l(d,e,n,i,u,c){return a(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="models-and-effort" tabindex="-1">Models and effort <a class="header-anchor" href="#models-and-effort" aria-label="Permalink to &quot;Models and effort&quot;">​</a></h1><p>The catalog comes from a live <code>model/list</code> call during plugin setup — never a hardcoded list. Each row becomes an OpenCode model built from the Muse profile plus model ID (for example <code>muse/muse-profile-tbh-model-muse-spark-1.3</code>), carrying the display label, context/output limits, release date, and known effort tiers.</p><h2 id="effort-variants" tabindex="-1">Effort variants <a class="header-anchor" href="#effort-variants" aria-label="Permalink to &quot;Effort variants&quot;">​</a></h2><p>Reasoning effort tiers (<code>minimal</code> … <code>max</code>, per-model subsets) appear as OpenCode model variants. The selected tier rides on that turn only (<code>turn/start.reasoningEffort</code>); the standing session default is untouched unless explicitly changed. If you pick nothing, the <code>default</code> variant resolves to the catalog row&#39;s default effort. Unknown variant names fail closed.</p><h2 id="logged-out-no-models-no-trap" tabindex="-1">Logged out? No models, no trap <a class="header-anchor" href="#logged-out-no-models-no-trap" aria-label="Permalink to &quot;Logged out? No models, no trap&quot;">​</a></h2><p>If the CLI reports no usable catalog (logged out, no subscription), the provider stays visible but disabled with a <em>&quot;Muse setup required&quot;</em> placeholder. OpenCode hides providers with zero models, so without the placeholder the Muse entry would vanish silently — the placeholder keeps the fix obvious.</p><h2 id="titles-and-summaries-are-local" tabindex="-1">Titles and summaries are local <a class="header-anchor" href="#titles-and-summaries-are-local" aria-label="Permalink to &quot;Titles and summaries are local&quot;">​</a></h2><p>Thread titles and compaction summaries never reach Muse: the bridge answers them deterministically from the request itself. A Muse turn costs real inference, and Muse already owns the authoritative conversation — spending a turn on bookkeeping OpenCode does for its own transcript would pollute Muse&#39;s history for nothing.</p>',8)])])}const f=o(r,[["render",l]]);export{m as __pageData,f as default};
